class Solution {
public:
    int myAtoi(string s) {
        long long res = 0; bool neg = 0; bool leading = true; 
        int n = s.size();
        for (int i = 0; i<n; i++) {
            if (s[i] == ' ') {
                if (leading) continue;
                else break;
            }
            else if (s[i] == '-') {
                if (i+1 < n && isdigit(s[i+1])) neg = 1;
                else break; 
            }
            else if (s[i] == '+') {
                if (i+1 < n && isdigit(s[i+1])) neg = 0;
                else break; 
            }
            else if (!isdigit(s[i])) break; 
            else {
                if (res < 1e11) {
                    res = res*10 + (s[i]-'0');
                    if (i+1 < n && !isdigit(s[i+1])){}
                        break;
                }
                else break;
                leading = false; 
            }
        }

        if (res > INT_MAX && neg) return INT_MIN;
        if (res > INT_MAX) return INT_MAX;
        return neg ? -1*res : res;
    }
};

