        if(tem==NULL && temp!=NULL)
        {
            while(temp!=NULL)
            {
                sum=temp->val+carry;
                valu=sum%10;
                carry=sum/10;
                ListNode* node =new ListNode(valu);
                ans->next=node;
                ans=ans->next;
                temp=temp->next;
            }
        }
        //if l2 gets over and there are still some elements in l1
        if(tem!=NULL && temp==NULL)
        {
            while(tem!=NULL)
            {
                sum=tem->val+carry;
                valu=sum%10;
                carry=sum/10;
                ListNode* node =new ListNode(valu);
                ans->next=node;
                ans=ans->next;
                tem=tem->next;
            }
        }
        //if there is still a carry left
        if(carry!=0)
        {
            ListNode* node =new ListNode(carry);
            ans->next=node;
        }
        return head;
    }
};

