class Solution {
public:
    double trimMean(vector<int>& arr) {
        int i, k;
        double mean;
        sort(arr.begin(), arr.end());
        k = 0.05*arr.size();
        for(i=0 ; i<k ; i++)
        {
            arr.erase(arr.begin()+0);
            arr.erase(arr.begin()+arr.size()-1);
        }
        mean = (double)accumulate(arr.begin(), arr.end(), 0)/arr.size();
        return mean;
    }
};

class Solution {
    int bs(vector<vector<Integer>>& items, int t, vector<int> &beauty) {
        int ans = 0, s = 0, e = items.size() - 1;
        while(s <= e) {
            int m = (s + e) / 2;
            if(items[m][0] <= t) ans = beauty[m], s = m + 1;
            else s = m + 1; 
        }
        return ans;
    }

public:
    vector<int> maximumBeauty(vector<vector<Integer>>& items, vector<int>& queries) {
        sort(items.begin(), items.end());
        vector<int> ans, beauty(items.size(), items[0][1]);

        for(int i=1; i<items.size(); i++) beauty[i] = max(beauty[i - 1], items[i][1]);

        for(int i : queries) ans.push_back(bs(items, i, beauty));
        return ans;
    }
};

