            }
            mp[nums[i]].second = i;
        }

        long long int totSum = calculateSum(nums);
        long long int left = nums[0];
        int ans = 0;

        for(int i=1; i<nums.size(); i++){
            long long int right = totSum - left;

            if(left == right){
                ans++;
            }
            else{
                long long int diff = left - right;
                long long int num = k - diff;

                if(mp.find(num) != mp.end()){
                    if(check(mp, num, i, 1)){
                        count[num].second++;
                    }
                }

                diff = right - left;
                num = k - diff;

                if(mp.find(num) != mp.end()){
                    if(check(mp, num, i, 0)){
                        count[num].first++; 
                    }
                }
            }

            left += nums[i];
            count[nums[i]].first = max(count[nums[i]].first, count[nums[i]].second);
        }

        int maxi = INT_MIN;
        for(auto [i,j] : count){
            maxi = max(maxi, max(j.first, j.second));
        }

        return max(maxi, ans);
    }
