        if(ind<0){return 0;}
        if(dp[days[ind]]!=-1){return dp[days[ind]];}
        int daypoint=costs[0]+helper(costs,days,ind-1,dp)
        int indweek=upper_bound(days.begin(),days.end(),days[ind-1]-7)-days.begin();
