            {
                cache[k++] = sums[j++];
            }

            cache[k++] = sums[i++];

            count += m-n;
        }

        while(j < right)
        {
            cache[k++] = sums[j++];
        }

        for(int idx = 0; idx<cache.size(); idx++)
        {
            sums[left + idx] = cache[idx];
        }

        return leftSideSum + rightSideSum;

