// **************** Using map *****************
class Solution {
public:
    long long dividePlayers(vector<int>& skill) {
        int n=skill.size();
        long long sum=accumulate(skill.begin(), skill.end(), 0);
        if(sum%(n/2)) return -1;
        long long skillTeam=sum/(n/2);

        unordered_map<int,int>mp;
        for(auto it: skill){
            mp[it]++;
        }

        long long ans=0;

        for(auto it: skill){
            if(mp.find(it)==mp.end()) continue;
            mp[it]--;

            int temp=skillTeam-it;
            if(mp.find(temp)!=mp.end()){
                mp[temp]--;
                if(mp[temp]==0) mp.erase(temp);
                ans+=it*temp;
                if(mp[it]==0) mp.erase(it);
            }
        }

        if(mp.size()>0) return -1;
        return ans;
    }
};

class LRUCache {
public:
class node
{
  public:
  int key;
  int val;
  node* next;
  node* prev;
  node(int _key,int _val)
  {
    key = _key;
    val = _val;
  }
};
node* head = new node(-1,-1);
node* tail = new node(-1,-1);

int size;
unordered_map<int,node*>mpp;
    LRUCache(int capacity) {
       size = capacity; 
       head->next = tail;
       tail->prev = head;  
    }

    void addNode(node* newNode){

       node* temp = head->next;
       newNode->next = temp;
       newNode->prev = head;
       head->next = newNode;
    }

    void deleteNode(node* delNode){

       node* delprev = delNode->prev;
       node* delnext = delNode->next;
       delprev->next = delnext;
       delnext->prev = delprev;
    }

    int get(int _key) {

        if(mpp.count(_key))
        {
          node* nde = mpp[_key];
          int curr = nde->val;
          mpp.erase(_key);
          deleteNode(nde);
          addNode(nde)
          mpp[_key] = head->next;
          return curr;
        }
        return -1;
    }

    void put(int _key, int value) {

        if(mpp.count(_key))
        {
           node* nde = mpp[_key];
           mpp.erase(_key);
           deleteNode(nde);
        }
        if(mpp.size()==size)
        {
           mpp.erase(tail->prev->key);
           deleteNode(tail->prev);
        }
        addNode(new node(_key,value));
        mpp[_key] = head->next;
    }
};

