class Solution {
public:
    int findPeakElement(vector<int>& nums) {
    int n=nums.size();
    if(n==1)
    {
      return 0;
    } 
    if(nums[0]>nums[1])
    {
      return 0;
    }
    if(nums[n-1]>nums[n-2])
    {
      return n-1;
    }
    int left=1;
    int right=n-2;
    while(left<=right)
    {
      int mid=(left+right)/2;
      if(nums[mid]>nums[mid-1]&& nums[mid]>nums[mid+1])
      {
        return mid;
      }
      else if(nums[mid]>nums[mid-1])
      {
        left=mid+1;
      }
      else{
        right=mid-1;
      }
    }
return -1;
    }
};

class Solution {
public:
    int distanceBetweenBusStops(vector<int>& distance, int start, int destination) {
        int i, dis1=0, dis2=0, j, temp;

        // Swapping the values of start and destination, if destination is smaller than start
        if(start>destination)
        {
            temp = start;
            start = destination;
            destination = temp;
        }

        //Checking Forward distance
        for(i=start ; i<destination ; i++)
        {
            dis1 += distance[i];
        }

        //Checking Backward distance
        i = start-1;
        j = distance.size()-destination+start;
        while(j>0)
        {
            if(i<0)
            {
                dis2 += distance[distance.size()+i];
            }
            else
                dis2 += distance[i]
            i--;
            j--;
        }

        // Result
        if(dis1<dis2)
            return dis1;
        return dis2;
    }
};

