    int mod=1e9+7
    int binExpo(long long x,long long n){
        int ans=1;
        while(n){
            if(n&1){
                ans=(ans*x)%mod;
            }
            x=(x*x)%mod;
            n>>=1;
        }
        return ans;
    }
