                    ends[j] = i;
                }
            }
        }

        int i = 0, j = 0;
        int ans = INT_MIN;
        while(j < n){

            if(ends[j] != -1){
                int st = ends[j];
                if(st < i){
                    ans = max(ans, j-i+1);
                }
                else{
                    i = st+1;
                    ans = max(ans, j-i+1);
                    j++;
                }
            }
            else ans = max(ans,j-i+1);
            j++;
        }
        return longestSubsequence(ans, ends);
    }

};

