    int getWays(int amount, vector<int> &coins){
        int st = 0;
        int ways_to_do[5001] = {0};

        if (coins[0] == 1)
        {
            for (int i = 1; i <= amount; i++)
                ways_to_do[i] = 1;
            st = 1;
        }

        ways_to_do[0] = 1;

        for (int i = st; i < coins.size(); i++)
