        {
            sum+=ele;
            Q.push(ele);

        }
        double half=sum/2;
        int count=0;
        while(sum>half)
        { 
            double max=Q.top();     
            Q.pop();                

            max/=2;                 
            Q.push(max);            
            count++;                

            sum-=max;               
        }

        displayResult(count);

    }

