            for(i = 0; i < n/2; i++){
                z = tmp[i]->val;
                tmp[i]->val = tmp[n-1-i]->val;
                tmp[n-1-i]->val = z;
            }
            x ^= 1;
            n = 0;
        }
        return root;
    }
};

class Solution {
public:

    // declare a dp

    int dp[105][10005];

    int helper(vector<int>& arr, int i, int n, int sum)
    {
        // base case

        if(sum == 0)
        {
            return 0;
        }

        if(i > n || sum < 0)
        {
            return INT_MAX - 1000;
        }

        // if already calculated

        if(dp[i][sum] != -1)
        {
            return dp[i][sum];
        }

        // at each ith element we have two options either include or exclude

        int mini = INT_MAX;

        // inclusion part

        if(arr[i] <= sum)
        {
            mini = min(mini, 1 + helper(arr, i, n, sum - arr[i]));
        }

        // exclusion part

        mini = min(mini, helper(arr, i + 1, n, sum));

        // store the res in dp

        return dp[i][sum] = mini;
    }

