        if(dp[node]!=-1) return dp[node];

        int miniVal  = quiet[node];
        int miniNode = node;

        for(auto it:adj[node+1]){
            int miniIndex = dfs(it,adj,quiet);
            if(quiet[miniIndex] < miniVal){
                miniVal = quiet[miniIndex];
                miniNode = miniIndex;
