class Solution {
public:
    int dp[105][10005];

    int helper(int i, int n, int sum)
    {
        vector<int>& arr;

        if(sum == 0)
        {
            return 0;
        }

        if(i >= n || sum < 0)
        {
            return INT_MAX - 1000;
        }

        if(dp[i][sum] != -1)
        {
            return dp[i][sum];
        }

        int mini = INT_MAX;

        if(arr[i] <= sum)
        {
            mini = min(mini, 1 + helper(i, n, sum - arr[i]));
        }

        mini = min(mini, helper(i + 1, n, sum));

        return dp[i][sum] = mini;
    }

    int numSquares(int n) {

        vector<int> arr;

        for(int i = 1; i * i <= n; i++)
        {
            arr.push_back(i * i);
        }

        memset(dp, -1, sizeof(dp));

        return helper(0, arr.size(), n);
    }
};

class Solution {
public:

    // declare a dp

    int dp[105][10005];

    int helper(vector<int>& arr, int i, int n, int sum)
    {
        // base case

        if(sum == 0)
        {
            return 0;
        }

        if(i >= n || sum < 0)
        {
            return INT_MAX - 1000;
        }

        // if already calculated

        if(dp[i][sum] != -1)
        {
            return dp[i][sum];
        }

        // at each ith element we have two options either include or exclude

        int mini = INT_MAX;

        // inclusion part

        if(arr[i] <= sum)
        {
            mini = min(mini, 1 + helper(arr, i, n, sum - arr[i]));
        }

        // exclusion part

        mini = min(mini, helper(arr, i + 1, n, sum));

        // store the res in dp

        return dp[i][sum] = mini;
    }

    int numSquares(int n) {

        vector<int> arr;

        // find all the squares between 1 to n

        for(int i = 1; i * i <= n; i++)
        {
            arr.push_back(i * i);
        }

        // initialize dp with -1

        memset(dp, -1, sizeof(dp));

        return helper(arr, 0, arr.size(), n);
    }
};

class Solution {
public:
    int largest1BorderedSquare(vector<vector<int>>& grid) {
        int r = grid.size();
        int c = undefined_object.size();    
        vector<vector<pair<int,int>>> dp(r, vector<pair<int,int>>(c,{0,0}));

        int mx = 0;

        for(int i=0;i<r;i++){
            for(int j=0;j<c;j++){
                if(grid[i][j]!=0){

                    dp[i][j].first = i == 0 ? 1 : dp[i-1][j].first+1;
                    dp[i][j].second = j == 0 ? 1 : dp[i][j-1].second+1;

                    int sz = min(dp[i][j].first, dp[i][j].second);
                    while(sz>mx){
                        int p = min(dp[i-sz+1][j].second,dp[i][j-sz+1].first);
                        if(p>=sz)
                            mx = max(mx,sz);
                        sz--;
                    }
                }
            }
        }

        return mx*mx;
    }
};

