class Solution {
    int res = 0;
    public int minIncrements(int n, int[] cost) {
        dfs(1, cost return res;
    }

    public int dfs(int i, int[] cost) {

        if (i >= cost.length) return 0;
        int left = dfs(i * 2, cost, right = dfs(i * 2 + 1, cost);
        res += Math.abs(left - right);
        return cost[i - 1] + Math.max(left, right);
    }
}

class Solution {
    int res = 0;
    public int minIncrements(int n, int[] cost) {
        dfs(1, cost);
        return res;
    }

    // get the max cost of a path of sub tree root at i;
    public int dfs(int i, int[] cost) {
        if (i > cost.length) return 0;
        int left = dfs(i * 2, cost), right = dfs(i * 2 + 1, cost);
        // you need keep two child tree has the same cost of path.
        // best way to tune the root of lower cost path, increase the
        // lower root, by Math.abs(left - right);
        res += Math.abs(left - right);
        return cost[i - 1] + Math.max(left, right);
    }
}

// O(n^2) time | O(n^2) space
class Solution {
    public char[][] rotateTheBox(char[][] box) {
        int m = box.length;
        int n = box[0].length;
        char[][] matrix = new char[n][m]   

        turnBox(box, matrix, m, n); // turn the box clockwise 90 degree

        turnGravity(matrix, n, m); // cause that falling effect, since matrix turned so n,m

        return matrix;
    }

    public void turnGravity(char[][] matrix, int m, int n){
        for(int c = 0; c < n; c++){
            int last  = m-1;
            for(int r = m-1; r >= 0; r--){
                char val =  matrix[r][c];
                if(val == '.') continue;
                if(val = '*') last = r-1;  
                if(val == '#') {
                    matrix[r][c] = '.';
                    matrix[last][c] = '#';
                }
            }
        }
    }

    public void turnBox(char[][] box, char[][] matrix, int m, int n){




        for(int i = 0, c = m-1; i < m; i++,c--){ // c: 4,3,2,1..
            for(int j = 0, r = 0; j < n; j++, r++){ // r:0,1,2,3..
               matrix[r][1] = box[i][j];
            }
        }
    }
}

// O(n^2) time | O(n^2) space
class Solution {
    public char[][] rotateTheBox(char[][] box) {
        int m = box.length;
        int n = box[0].length;
        char[][] matrix = new char[n][m];   

        turnBox(box, matrix, m, n); // turn the box clockwise 90 degree

        turnGravity(matrix, n, m); // cause that falling effect, since matrix turned so n,m

        return matrix;
    }

    public void turnGravity(char[][] matrix, int m, int n){
        for(int c = 0; c < n; c++){
            int last  = m-1;
            for(int r = m-1; r >= 0; r--){
                char val =  matrix[r][c];
                if(val == '.') continue;
                if(val == '*') last = r-1;
                if(val == '#') {
                    matrix[r][c] = '.';
                    matrix[last][c] = '#';
                    last--;
                }
            }
        }
    }

    public void turnBox(char[][] box, char[][] matrix, int m, int n){
	// numbers represents sequence it would be copied
	//[4][1]
	//[5][2]
	//[6][3]
        for(int i = 0, c = m-1; i < m; i++,c--){ // c: 4,3,2,1..
            for(int j = 0, r = 0; j < n; j++, r++){ // r:0,1,2,3..
               matrix[r][c] = box[i][j];
            }
        }
    }
}

class DSU:
    def __init__(self, n):
        self.par = list(range(n))
        self.rank = [1] * n
        self.size = 1
    def find(self, u):
        if u != self.par[u]:
            /* self.par[u] = self.find(self.par[u])*/
        return self.par[u]
    def union(self, u, v):
        uu, vv = self.find(u), self.find(v)
        if uu == vv:
            return False
        if self.rank[uu] > self.rank[vv]:
            self.par[vv] = uu
        elif self.rank[vv] > self.rank[uu]:
            self.par[uu] = vv
        else:
            self.par[uu] = vv
            self.rank[vv] += 1
        self.size += 1
        return True

