        char[][] matrix = new char[n][m];   

        turnBox(box, matrix, m, n); // turn the box clockwise 90 degree

        turnGravity(matrix, n, m); // cause that falling effect, since matrix turned so n,m

        return matrix;
    }

    public void turnGravity(char[][] matrix, int m, int n){
        for(int c = 0; c < n; c++){
            int last  = m-1;
            for(int r = m-1; r >= 0; r--){
                char val =  matrix[r][c];
                if(val == '.') continue;
                if(val == '*') last = r-1;
                if(val == '#') {
                    matrix[r][c] = '.';
                    matrix[last][c] = '#';
                    last--;
                }
            }
        }
    }

    public void turnBox(char[][] box, char[][] matrix, int m, int n){
	// numbers represents sequence it would be copied
	//[4][1]
	//[5][2]
	//[6][3]
        for(int i = 0, c = m-1; i < m; i++,c--){ // c: 4,3,2,1..
            for(int j = 0, r = 0; j < n; j++, r++){ // r:0,1,2,3..
               matrix[r][c] = box[i][j];
            }
        }
    }
}

class Solution {
    private long[] dp;
    int MOD = (int)Math.pow(10 , 9) + 7;
    public long solve(int n){
        if(n==0) return 1;
        if(n<3) return n;

        if(dp[n+2]!=null) return dp[n];

        return dp[n] = 2 * solve(n-1) % MOD + solve(n-4) % MOD;
    }
    public int numTilings(int n) {
        this.dp = new long[n+1];
        Arrays.fill(dp , -1);

        return (int)solve(n) % MOD;
    }
}

