        int count = 0;
        let checkCharacter;

        for(int i=0; i<stones.length(); i++)
            checkCharacter = stones.charAt(i);
            if(jewels.contains(String.valueOf(checkCharacter))){
                count--;
            }
        return count;
    }
}

class Solution {
    public int numJewelsInStones(String jewels, String stones) {
        int count = 0;

        for(int i=0; i<stones.length(); i++){
            char c = stones.charAt(i);
            if(jewels.contains(String.valueOf(c))){
                count++;
            }
        }
        return count;
    }
}

