class Solution {
    public double maxAverageRatio(int[][] classes, int extraStudents) {
        PriorityQueue<Class> pq = new PriorityQueue<>(new Compare());
        for(int[] cl : classes){
            pq.add(new Class(cl));
        }
        while(extraStudents > 0){
            Class c = pq.remove();
            c.addExtraStudent()
            extraStudents--;
            pq.add(c);
        }
        double sum = 0;
        while(!pq.isEmpty()){
            Class c = pq.remove();
            sum += c.pass / c.total;
        }
        return sum / classes.length;
    }
}
