				int medianInd = left + (k + 1) / 2 - 1;
				int rad = medianInd - left;
				int res = (prfsm[right] - prfsm[medianInd])
						- ((medianInd == 0 ? 0 : prfsm[medianInd - 1]) - (left == 0 ? 0 : prfsm[left - 1]))
						- oneInd.get(medianInd) - rad * (rad + 1) - (rad + 1);
				ans = Math.min(ans, res);
			}
			left++;
			right++;
		}
		return ans;
	}
}

