class Solution {
    public void nextPermutation(int[] n) {
        //breakpoint
       if(  n==null || n.length<=1)return;

		int i = n.length-2;

		while(i>=0 && n[i]>=n[i+1])i--;

		int j=n.length-1;

		if(i>=0) {
			while(n[j]>=n[i])j--;
			swap(n,i,j);
		}

