        int ans = 0;
        int lo=0, hi=2;
        if(amount[0] == 0) lo++;
        if(lo==1 && amount[1]==0) return amount[2];

        else if(lo==1){
            ans += amount[hi];
            return ans;
        }
        while(amount[lo] != 0){
            ans++;
