/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    int index;
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        Map<Integer, Integer> m = new HashMap<>();

        for(int i = 0; i < inorder.length; i++) {
            m.put(inorder[i], i);
        }
        index = postorder.length - 1;
        return buildTree(0, postorder.length - 1, postorder, m);
    }

    private TreeNode buildTree(int l, int r, int postorder[] , Map<Integer, Integer> m) {
        if(l > r) return null;

        int val = postorder[index];
        index--;

        TreeNode root = new TreeNode(val);
        if(l == r) return root;

        int in = m.get(val);

        root.right = null;
        root.left = buildTree(l, in - 1, postorder, m);

        return root;
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    int index;
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        Map<Integer, Integer> m = new HashMap<>();

        for(int i = 0; i < inorder.length; i++) {
            m.put(inorder[i], i);
        }
        index = postorder.length - 1;
        return buildTree(0, postorder.length - 1, postorder, m);
    }

    private TreeNode buildTree(int l, int r, int postorder[] , Map<Integer, Integer> m) {
        if(l > r) return null;

        int val = postorder[index];
        index--;

        TreeNode root = new TreeNode(val);
        if(l == r) return root;

        int in = m.get(val);

        root.right = buildTree(in + 1, r, postorder, m);
        root.left = buildTree(l, in - 1, postorder, m);

        return root;
    }
}

class Graph {
    List<List<int[]>> adj;
    int n;
    public Graph(int n, int[][] edges) {
        for(int i=0;i<n;i++){
            adj.add(new ArrayList<>());
        }
        this.n=n;
        for(int edge[]: edges){
            adj.get(edge[0]).add(new int[]{edge[1],edge[2]});
        }
    }

    public void addEdge(int[] edge) {
        adj.get(edge[0]).add(new int[]{edge[1],edge[2]});
    }

    public int shortestPath(int node1, int node2) {
        int dist[]=new int[n+1];
        Arrays.fill(dist,Integer.MAX_VALUE);
        dist[node1]=0;
        PriorityQueue<int[]> pq=new PriorityQueue<>((a,b)->a[1]-b[1]);
        pq.add(new int[]{node1,0});
        while(!pq.isEmpty()){
            int u=pq.poll()[0];
            for(int p[]: adj.get(u)){
                int v=p[0];
                int w=p[1];
                if(dist[v]>dist[u]+w){
                    dist[v]=dist[u]+w;
                    pq.add(new int[]{v,dist[v]});
                }
            }
        }
        if(dist[node2]==Integer.MAX_VALUE){
                return -1;
        }
        return dist[node2];
    }

}

