                    ListNode prev = ptr.next;
                    while(cur != end) {
                        next = cur.next;
                        cur.next = prev;
                        prev = cur;
                        cur = next;
                    }
                    // connect
                    last.next = prev;
                    ptr = left;

                }
                last = ptr;
                left = ptr.next;
                count = 0;
                groupSize++;
            }
            ptr = ptr.next;
        }

        if(count > 0 && count % 2 == 0) {
