        st.push(-1);
        int n = 0;
        for(int i = 0; i < s.length(); i++)
        {
            if(s.charAt(i) == '(')
                st.push(i);
            else if(s.charAt(i) == ')')
            {
                st.pop();
                if(st.empty())
                    st.push(i);
                else
                    n = Math.max(n, i - st.peek());
            }
        }
        return n;
    }
}

class Solution {
    public int subtractProductAndSum(int n) {

        int multi=1, sum=0;
        while(n!=0){
            int rem=n%10; //take last digit of n
            sum+=rem;
            multi*=rem;
            n=n/10; // dropping last digit of n
        }
        // System.out.println(multi+" "+sum);
        return multi - sum;
    }
    public static void main(String[] args) {
        int n = 234;
        System.out.println("The difference is " + subtractProductAndSum(n);
    }
}

