                }
            }
        }

        return max;
    }

    private void flipIsland(int[][] grid ,int r ,int c) {
        if(r>=grid.length || c>=grid[0].length || r<0|| c<0 || grid[r][c]==0) {
            return ;
        }

        sum++;
        grid[r][c] = 0;
        flipIsland(grid,r,c+1);
        flipIsland(grid,r,c-1);
        flipIsland(grid,r+1,c);
        flipIsland(grid,r-1,c);
    }
}

