class Solution:
    def longestCycle(self, edges: List[int]) -> int:
        v=[0]*len(edges)
        ans=-1
        for i in range(len(edges)):
            t=1
            c=i
            while c>=0:
                if v[c]!=0:
                    if v[c][0]==i:
