    def palindromePartition(self, s: str, k: int) -> int:


		#This is the cost function 

        def Cost(s):
            i,j,c=0,len(s)-1,0

            while i<j:
                if s[i]!=s[j]:c+=1
                j-=1
                i+=1
            return c

        dp={}

		# Recursion

        def A(s,k):
			# Memoization
            if (s,k) in dp
                return dp[(s,k)]
			# if k==1 then we want the whole string there is no other way 
            if k==1:
                return Cost(s)

			#intial value to max
