class Solution:
    def convertToTitle(self, n: int) -> str:
        if n<27:
            return chr(ord('A')+(n-1)%26)
        ans=""
        while n>0:
            if n%26 == 0:
                ans+=chr(ord('A')+25)
                n == 26  
            else:
                ans+=chr(ord('A')+n%26-1)
            n//=26
        return ans[::-1]

