    public void test1() {
        Map<List<String>, Integer> graph = new HashMap<>();
        graph.put(new ArrayList<String>(Arrays.asList("A", "C")), 3);
        graph.put(new ArrayList<String>(Arrays.asList("A", "F")), 5);
