        Node node3 = new Node("3", new ArrayList<Node>(Arrays.asList(node4)));
        Node node2 = new Node("2", new ArrayList<Node>(Arrays.asList(node1, node3, node4)));
        Node node0 = new Node("0", new ArrayList<Node>(Arrays.asList(node2, node5)));

